const saved=(()=>{for(const k of [LS,OLD_LS])try{const v=JSON.parse(localStorage.getItem(k)||'null');if(v)return v}catch{}return{}})();
const ps={projects:[],project:null,slideId:null,slideAnchorId:null,selectedSlides:new Set(),elementId:null,selectedElements:new Set(),query:'',zoom:saved.zoom||1,fitScale:1,sidebar:saved.sidebar||292,sidebarOpen:saved.sidebarOpen!==false,window:saved.window||null,props:saved.props||{dx:null,dy:82,w:320,h:650,open:true},toolbar:saved.toolbar||{x:14,y:12},saveTimer:null,loading:false,space:false,pan:null,windowZoomed:false,preZoom:null,toolMode:'slide',grid:!!saved.grid,gridSize:saved.gridSize||32,history:[],redo:[],drag:null,thumbDrag:null,openedOnce:false,fonts:[],bible:{manifest:null,books:[],byId:{},aliases:[],cache:new Map()},present:{open:false,index:0,scale:1,black:false}};

function persist(){try{localStorage.setItem(LS,JSON.stringify({zoom:ps.zoom,sidebar:ps.sidebar,sidebarOpen:ps.sidebarOpen,window:ps.window,props:ps.props,toolbar:ps.toolbar,grid:ps.grid,gridSize:ps.gridSize}))}catch{}}
function toast(m){window.TahoeAdmin?.toast?.(m)}
function currentSlide(){return ps.project?.slides?.find(s=>s.id===ps.slideId)||ps.project?.slides?.[0]||null}
function currentElement(){return currentSlide()?.elements?.find(e=>e.id===ps.elementId)||null}
function normalizeProject(p){
 p=clone(p||{});p.id=p.id||uid();p.title=p.title||'ព្រះបន្ទូល';p.date=p.date||new Date().toISOString().slice(0,10);p.service=p.service||'09:30';p.ratio=p.ratio==='4:3'?'4:3':'16:9';
 p.master=p.master||{};Object.assign(p.master,{theme:p.master.theme||'sunday-dark',bg:p.master.bg||'#07110d',fg:p.master.fg||'#f8fbf9',accent:p.master.accent||'#59e9ae',titleFont:p.master.titleFont||'SONYHEAD5',bodyFont:p.master.bodyFont||'Krasar',verseNumberStyle:p.master.verseNumberStyle||'normal'});
 p.slides=Array.isArray(p.slides)?p.slides:[];p.slides.forEach(s=>{s.id=s.id||uid();s.name=s.name||s.title||'Slide';s.elements=Array.isArray(s.elements)?s.elements:[];s.elements.forEach(e=>{e.id=e.id||uid();e.rotation=Number(e.rotation)||0;e.opacity=e.opacity==null?1:Number(e.opacity);e.z=Number(e.z)||1;e.lineHeight=Number(e.lineHeight)||((e.type==='bible'||e.role==='bibleText')?1.42:1.35)})});
 if(!p.slides.length)p.slides.push(makeSlide(true,p));return p
}
function baseElement(type='text',opt={}){return Object.assign({id:uid(),type,x:10,y:20,w:80,h:20,rotation:0,opacity:1,z:1,fontFamily:ps.project?.master?.bodyFont||'Krasar',fontSize:36,color:ps.project?.master?.fg||'#fff',fill:'transparent',bold:false,italic:false,underline:false,align:'center',valign:'center',lineHeight:1.35,text:'',ref:'',data:'',fit:'contain',radius:0,role:''},opt)}
function makeSlide(title=false,project=ps.project){const s={id:uid(),name:title?'Title':'Slide',elements:[]};if(title)s.elements.push(baseElement('text',{x:8,y:30,w:84,h:32,text:project?.title||'ព្រះបន្ទូល',fontSize:62,bold:true,align:'center',valign:'center',fontFamily:project?.master?.titleFont||'SONYHEAD5',color:project?.master?.fg||'#f8fbf9',role:'title'}));return s}
function makeProject(title='ព្រះបន្ទូល',ratio='16:9'){const p={id:uid(),title:(title||'ព្រះបន្ទូល').trim()||'ព្រះបន្ទូល',date:new Date().toISOString().slice(0,10),service:'09:30',ratio:ratio==='4:3'?'4:3':'16:9',master:{theme:'sunday-dark',bg:'#07110d',fg:'#f8fbf9',accent:'#59e9ae',titleFont:'SONYHEAD5',bodyFont:'Krasar',verseNumberStyle:'normal'},slides:[],createdAt:Date.now(),updatedAt:Date.now()};p.slides=[makeSlide(true,p)];return normalizeProject(p)}
function projectFileName(p){const clean=String(p?.title||'ព្រះបន្ទូល').replace(/[\\/:*?"<>|]/g,'-').replace(/\s+/g,' ').trim().slice(0,90)||'ព្រះបន្ទូល';return `${clean}.powerslide`}
function slideText(s){return (s?.elements||[]).filter(e=>['text','bible'].includes(e.type)).map(e=>e.text||'').join(' ').trim()}
function snapshot(){return ps.project?JSON.stringify(ps.project):''}
function pushHistory(){if(!ps.project)return;ps.history.push(snapshot());if(ps.history.length>60)ps.history.shift();ps.redo=[]}
function undo(){if(!ps.history.length||!ps.project)return;ps.redo.push(snapshot());ps.project=normalizeProject(JSON.parse(ps.history.pop()));ensureSelections();dirty(true,false)}
