function ensureSelections(){if(!ps.project)return;ps.slideId=ps.project.slides.some(s=>s.id===ps.slideId)?ps.slideId:ps.project.slides[0]?.id||null;ps.selectedSlides=new Set([...ps.selectedSlides].filter(id=>ps.project.slides.some(s=>s.id===id)));if(ps.slideId&&!ps.selectedSlides.size)ps.selectedSlides.add(ps.slideId);const s=currentSlide();ps.elementId=s?.elements.some(e=>e.id===ps.elementId)?ps.elementId:null;ps.selectedElements=new Set([...ps.selectedElements].filter(id=>s?.elements.some(e=>e.id===id)));if(ps.elementId&&!ps.selectedElements.size)ps.selectedElements.add(ps.elementId)}

function profile(){return window.TahoeAdmin?.state?.().profile||{}}
function updateProfile(){const p=profile(),avatar=$('#psnAccountAvatar'),name=$('#psnAccountName'),sub=$('#psnAccountSubtitle');if(name)name.textContent=p.displayName||p.email?.split('@')[0]||'User';if(sub)sub.textContent=p.subtitle||'Account';if(avatar)avatar.innerHTML=p.photoURL?`<img src="${esc(p.photoURL)}" alt="">`:esc((p.displayName||p.email||'U').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase())}
function canOpen(){try{return typeof canUseDesktopApps==='function'?canUseDesktopApps():false}catch{return false}}
function updateAccess(){launcher.style.display=canOpen()?'grid':'none';if(!canOpen())close()}

async function loadFonts(){if(ps.fonts.length)return;let rows=[];try{const j=await fetch('assets/fonts/fonts.json',{cache:'no-store'}).then(r=>r.ok?r.json():null);rows=j?.fonts||[]}catch{}const names=['Krasar','Kantumruy Pro','Battambang','Hanuman','Noto Sans Khmer','Noto Serif Khmer','Siemreap','Moul','Moulpali','Bayon','Dangrek','Content','Freehand','Khmer','Koulen','Metal','Odor Mean Chey','Preahvihear','Taprom'];const base=[...names.map(x=>({id:x,name:x,family:x})),{id:'SONYHEAD5',name:'SONY HEAD5',family:'SONYHEAD5'},{id:'system',name:'System',family:'system-ui'}];ps.fonts=[...new Map([...base,...rows.map(f=>({id:f.id||f.family,name:f.name||f.family||f.id,family:f.family||f.id}))].map(f=>[f.id,f])).values()]}
function fontOptions(selected){return ps.fonts.map(f=>`<option value="${esc(f.id)}"${f.id===selected?' selected':''}>${esc(f.name)}</option>`).join('')}

const KM='០១២៣៤៥៦៧៨៩';function toKm(v){return String(v).replace(/\d/g,d=>KM[+d])}function fromKm(v){return String(v).replace(/[០-៩]/g,d=>KM.indexOf(d))}function norm(s){return fromKm(String(s||'')).normalize('NFKC').toLowerCase().replace(/[\u200b\u200c\u200d\s._-]/g,'')}
async function loadBible(){if(ps.bible.manifest)return;try{const m=await fetch('data/manifest.json',{cache:'no-store'}).then(r=>r.json());ps.bible.manifest=m;ps.bible.books=[...m.books].sort((a,b)=>a.order-b.order);ps.bible.byId=Object.fromEntries(ps.bible.books.map(b=>[b.id,b]));const a=new Map(),add=(name,id)=>{const n=norm(name);if(n)a.set(n,id)};ps.bible.books.forEach(b=>{add(b.nameKm,b.id);const compact=b.nameKm.replace(/ទី\s*/g,'');add(compact,b.id);const n=norm(compact),mm=n.match(/^(.*?)([123])$/);if(mm){add(mm[2]+mm[1],b.id);add(mm[1]+'ទី'+mm[2],b.id)}});Object.entries({'ហេព្រើ':'HEB','ហេប្រឺ':'HEB','អេភេសូរ':'EPH','អេភេសូ':'EPH','ភីលីព':'PHP','រ៉ូម':'ROM','កិច្ចការ':'ACT','កិច្ចការរបស់ពួកសាវក':'ACT','យ៉ូហាន':'JHN','ម៉ាថាយ':'MAT','ម៉ាកុស':'MRK','លូកា':'LUK','1កូរិនថូស':'1CO','កូរិនថូស1':'1CO','2កូរិនថូស':'2CO','កូរិនថូស2':'2CO','ទំនុកតម្កើង':'PSA','ទំនុកដំកើង':'PSA','ទំនុកតំកើង':'PSA','1សាំយូអែល':'1SA','1សាំយ៉ូអែល':'1SA','2សាំយូអែល':'2SA','2សាំយ៉ូអែល':'2SA','1យ៉ូហាន':'1JN','2យ៉ូហាន':'2JN','3យ៉ូហាន':'3JN','ចោទិយកថា':'DEU','ទុតិយកថា':'DEU','និក្ខមនំ':'EXO'}).forEach(([n,id])=>add(n,id));ps.bible.aliases=[...a.entries()].sort((x,y)=>y[0].length-x[0].length)}catch(e){console.warn('PowerSlide Bible manifest',e)}}
async function loadBook(id){if(ps.bible.cache.has(id))return ps.bible.cache.get(id);const b=await fetch(`data/books/${id}.json`).then(r=>{if(!r.ok)throw Error(id);return r.json()});ps.bible.cache.set(id,b);return b}
function editDistance(a,b){if(a===b)return 0;let p=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const c=[i];for(let j=1;j<=b.length;j++)c[j]=Math.min(c[j-1]+1,p[j]+1,p[j-1]+(a[i-1]===b[j-1]?0:1));p=c}return p[b.length]}
function resolveBookToken(token){const t=norm(token);for(const [a,id] of ps.bible.aliases)if(t===a)return{id};let best=null;for(const [a,id] of ps.bible.aliases){const d=editDistance(t,a),lim=Math.max(1,Math.min(3,Math.floor(Math.max(t.length,a.length)*.2)));if(d<=lim&&(!best||d<best.d))best={id,d}}return best}
function parseRef(q){if(!ps.bible.manifest)return null;let n=fromKm(String(q||'')).normalize('NFKC').toLowerCase().replace(/[\u200b\u200c\u200d]/g,'').replace(/[：]/g,':').replace(/[–—−]/g,'-').trim().replace(/^[•·▪◦*\-]+\s*/,'').replace(/[។៕;,]+\s*$/,'').replace(/\s+/g,'');for(const [a,id] of ps.bible.aliases){if(!n.startsWith(a))continue;const m=n.slice(a.length).match(/^(\d+)(?::(\d+)(?:-(\d+))?)?$/);if(!m)continue;const chapter=+m[1],start=m[2]?+m[2]:1,end=m[3]?+m[3]:start;if(chapter>=1&&chapter<=ps.bible.byId[id].chapterCount&&start>=1&&end>=start)return{book:id,chapter,start,end}}const m=n.match(/^(.*?)(\d+)(?::(\d+)(?:-(\d+))?)?$/);if(!m)return null;const b=resolveBookToken(m[1]);if(!b)return null;const chapter=+m[2],start=m[3]?+m[3]:1,end=m[4]?+m[4]:start;if(chapter<1||chapter>ps.bible.byId[b.id].chapterCount||start<1||end<start)return null;return{book:b.id,chapter,start,end}}
async function passage(ref){await loadBible();const r=parseRef(ref);if(!r)throw Error('Bible reference not recognized');const b=await loadBook(r.book),ch=b.chapters[String(r.chapter)],meta=ps.bible.byId[r.book];if(!ch)throw Error('Chapter not found');const rows=[];for(let v=r.start;v<=r.end;v++){const t=ch.verses[String(v)];if(t)rows.push({v,text:t})}if(!rows.length)throw Error('Verses not found');return{...r,reference:`${meta.nameKm} ${toKm(r.chapter)}:${toKm(r.start)}${r.end!==r.start?'–'+toKm(r.end):''}`,rows,text:rows.map(x=>`${toKm(x.v)} ${x.text}`).join('\n')}}

function isTextElement(e){return !!e&&['text','bible'].includes(e.type)}
function elStyle(e){const va=e.valign==='top'?'flex-start':e.valign==='bottom'?'flex-end':'center';return `left:${Number(e.x)||0}%;top:${Number(e.y)||0}%;width:${Number(e.w)||20}%;height:${Number(e.h)||12}%;z-index:${Number(e.z)||1};opacity:${e.opacity??1};transform:rotate(${Number(e.rotation)||0}deg);font-size:${Math.max(4,Number(e.fontSize)||32)}px;font-weight:${e.bold?700:400};font-style:${e.italic?'italic':'normal'};text-decoration:${e.underline?'underline':'none'};text-align:${e.align||'left'};line-height:${Number(e.lineHeight)||1.35};color:${esc(e.color||ps.project?.master?.fg||'#fff')};font-family:${esc(e.fontFamily||ps.project?.master?.bodyFont||'Krasar')};border-radius:${Number(e.radius)||0}px;align-items:${va}`}
function bibleTextHTML(text){const sup=ps.project?.master?.verseNumberStyle==='superscript';return String(text||'').split(/\n+/).filter(Boolean).map(line=>{const m=line.match(/^\s*([០-៩0-9]+)\s+(.*)$/);return m?`<span class="psn-verse-line"><span class="psn-verse-no${sup?' superscript':''}">${esc(m[1])}</span> <span>${esc(m[2])}</span></span>`:`<span class="psn-verse-line">${esc(line)}</span>`}).join('')}
function elementInner(e){if(e.type==='image'&&e.data)return `<img src="${esc(e.data)}" alt="" style="width:100%;height:100%;object-fit:${esc(e.fit||'contain')};border-radius:inherit">`;if(e.type==='shape')return '';if(e.type==='bible')return `${e.ref?`<div class="psn-bible-ref">${esc(e.ref)}</div>`:''}<div>${bibleTextHTML(e.text)}</div>`;if(e.role==='bibleText')return bibleTextHTML(e.text);return esc(e.text||'').replace(/\n/g,'<br>')}
function elementHTML(e){const selected=ps.selectedElements.has(e.id)||ps.elementId===e.id,primary=ps.elementId===e.id;const shape=e.type==='shape'?`;background:${esc(e.fill||ps.project?.master?.accent||'#59e9ae')};border-radius:${Number(e.radius)||0}px`:e.fill&&e.fill!=='transparent'?`;background:${esc(e.fill)}`:'';return `<div class="psn-canvas-el${selected?' selected':''}${primary?' primary':''}" data-el="${esc(e.id)}" data-type="${esc(e.type||'text')}" style="${elStyle(e)}${shape}"><div class="psn-el-content"${['text','bible'].includes(e.type)?' data-editable="1"':''}>${elementInner(e)}</div>${primary?'<span class="psn-selection-label">'+esc(e.type||'text')+'</span><span class="psn-rotate-line"></span><span class="psn-rotate-handle" data-el-rotate></span><span class="psn-resize-handle" data-el-resize></span>':''}</div>`}
function fitTextNode(node,e){if(!node||!isTextElement(e)||node.classList.contains('editing'))return Number(e?.fontSize)||32;const c=node.querySelector('.psn-el-content')||node,boxW=Math.max(1,node.clientWidth),boxH=Math.max(1,node.clientHeight),base=Math.max(4,Number(e.fontSize)||32);c.style.fontSize=base+'px';const over=()=>c.scrollHeight>boxH+1||c.scrollWidth>boxW+1;if(!over()){node.dataset.fitPx=String(base);node.dataset.fit='100';return base}let lo=4,hi=base,best=4;c.style.fontSize=lo+'px';for(let i=0;i<12;i++){const mid=(lo+hi)/2;c.style.fontSize=mid+'px';if(over())hi=mid;else{best=mid;lo=mid}}best=Math.max(4,Math.min(base,best));c.style.fontSize=best+'px';node.dataset.fitPx=String(best);node.dataset.fit=String(Math.round(best/base*100));return best}
function fitTextElements(root,slide){if(!root||!slide)return;root.querySelectorAll('[data-el]').forEach(node=>{const e=slide.elements?.find(x=>x.id===node.dataset.el);if(e)fitTextNode(node,e)})}
function scheduleTextFit(root,slide){requestAnimationFrame(()=>{fitTextElements(root,slide);if(document.fonts?.ready)document.fonts.ready.then(()=>fitTextElements(root,slide)).catch(()=>{})})}
function thumbHTML(s,i){const ratio=ps.project?.ratio==='4:3'?' ratio43':'',sel=ps.selectedSlides.has(s.id),active=s.id===ps.slideId,bg=esc(s.background||ps.project?.master?.bg||'#07110d');return `<button class="psn-slide-item${active?' active':''}${sel&&ps.selectedSlides.size>1?' multi':''}" draggable="true" data-slide="${esc(s.id)}"><span class="psn-slide-num">${i+1}</span><span class="psn-thumb${ratio}" style="background:${bg}"><span class="psn-thumb-inner">${(s.elements||[]).sort((a,b)=>(a.z||1)-(b.z||1)).map(e=>`<span class="psn-thumb-el" data-el="${esc(e.id)}" style="${elStyle(e)}${e.type==='shape'?`;background:${esc(e.fill||ps.project?.master?.accent||'#59e9ae')};border-radius:${Number(e.radius)||0}px`:e.fill&&e.fill!=='transparent'?`;background:${esc(e.fill)}`:''}"><span class="psn-el-content">${elementInner(e)}</span></span>`).join('')}</span></span></button>`}
function scaleThumbs(){$$('#psnSlideList .psn-thumb').forEach(t=>{const inner=t.querySelector('.psn-thumb-inner');if(!inner)return;const item=t.closest('[data-slide]'),slide=ps.project?.slides?.find(s=>s.id===item?.dataset.slide),base=ps.project?.ratio==='4:3'?720:960,scale=t.clientWidth/base;inner.style.transform=`scale(${scale})`;inner.style.width=base+'px';inner.style.height='540px';if(slide)fitTextElements(inner,slide)})}
function renderSlides(){const list=$('#psnSlideList');if(!list)return;const title=$('#psnFileTitle');if(title)title.textContent=ps.project?.title||'ព្រះបន្ទូល';if(!ps.project){list.innerHTML='';return}const q=ps.query.trim().toLowerCase(),rows=ps.project.slides.map((s,i)=>({s,i})).filter(({s,i})=>!q||String(i+1).includes(q)||slideText(s).toLowerCase().includes(q));list.innerHTML=rows.length?rows.map(({s,i})=>thumbHTML(s,i)).join(''):`<div class="psn-props-empty">No matching slides</div>`;$('#psnProjectPill')?.replaceChildren(document.createTextNode(`${ps.project.title} · ${ps.project.slides.length} slides`));requestAnimationFrame(scaleThumbs)}
function renderCanvas(){const c=$('#psnSlideCanvas'),s=currentSlide();if(!c)return;c.classList.toggle('ratio43',ps.project?.ratio==='4:3');c.classList.toggle('grid-on',ps.grid);c.style.setProperty('--psn-grid',ps.gridSize+'px');c.style.background=s?.background||ps.project?.master?.bg||'#07110d';c.innerHTML=s?(s.elements||[]).sort((a,b)=>(a.z||1)-(b.z||1)).map(elementHTML).join(''):`<div class="psn-empty">Open or create a project.</div>`;if(s)scheduleTextFit(c,s);renderProperties();requestAnimationFrame(fitCanvas)}
function renderAll(){ensureSelections();renderSlides();renderCanvas();updateSaveState('Saved');updateToolbarStates()}

function fitCanvas(){const work=$('#psnStageScroll'),shell=$('#psnCanvasShell'),canvas=$('#psnSlideCanvas');if(!work||!shell||!canvas)return;const w=ps.project?.ratio==='4:3'?720:960,h=540,pad=76,availW=Math.max(160,work.clientWidth-pad),availH=Math.max(120,work.clientHeight-pad);ps.fitScale=Math.min(availW/w,availH/h);const scale=ps.fitScale*ps.zoom;shell.style.width=(w*scale)+'px';shell.style.height=(h*scale)+'px';canvas.style.transform=`scale(${scale})`;const z=$('#psnZoomLabel');if(z)z.textContent=Math.round(ps.zoom*100)+'%';if(ps.zoom<=1.001){work.scrollLeft=0;work.scrollTop=0}}
function setZoom(z){ps.zoom=clamp(Number(z)||1,.25,4);persist();fitCanvas()}
function resetFit(){ps.zoom=1;persist();fitCanvas()}

function selectedSlideObjects(){return ps.project?.slides?.filter(s=>ps.selectedSlides.has(s.id))||[]}
function selectSlideOnly(id){ps.slideId=id;ps.slideAnchorId=id;ps.selectedSlides=new Set(id?[id]:[]);ps.elementId=null;ps.selectedElements.clear();renderAll();requestAnimationFrame(()=>document.querySelector(`[data-slide="${CSS.escape(id)}"]`)?.scrollIntoView({block:'nearest'}))}
function toggleSlideSelection(id){ps.selectedSlides.has(id)&&ps.selectedSlides.size>1?ps.selectedSlides.delete(id):ps.selectedSlides.add(id);ps.slideId=id;ps.slideAnchorId=id;ps.elementId=null;ps.selectedElements.clear();renderAll()}
function rangeSelectSlides(id){const a=ps.project.slides.findIndex(s=>s.id===ps.slideAnchorId),b=ps.project.slides.findIndex(s=>s.id===id);if(a<0||b<0)return selectSlideOnly(id);ps.selectedSlides=new Set(ps.project.slides.slice(Math.min(a,b),Math.max(a,b)+1).map(s=>s.id));ps.slideId=id;ps.elementId=null;ps.selectedElements.clear();renderAll()}
function addSlide(afterId=null){if(!ps.project)return;pushHistory();const s=makeSlide(false);let i=afterId?ps.project.slides.findIndex(x=>x.id===afterId):-1;if(i<0)i=ps.project.slides.length-1;ps.project.slides.splice(i+1,0,s);selectSlideOnly(s.id);dirty(true);requestAnimationFrame(()=>document.querySelector(`[data-slide="${CSS.escape(s.id)}"]`)?.scrollIntoView({block:'nearest'}))}
