function balancedVerseGroups(rows,parts){parts=Math.max(1,Math.min(parts,rows.length));const total=rows.reduce((n,r)=>n+r.length,0),out=[],target=total/parts;let cur=[],chars=0,remain=parts;for(let i=0;i<rows.length;i++){const r=rows[i],left=rows.length-i;if(cur.length&&remain>1&&chars+r.length>target&&left>=remain){out.push(cur);cur=[];chars=0;remain--}cur.push(r);chars+=r.length}if(cur.length)out.push(cur);while(out.length<parts){const i=out.findIndex(g=>g.length>1);if(i<0)break;const g=out[i],cut=Math.ceil(g.length/2);out.splice(i,1,g.slice(0,cut),g.slice(cut))}return out}
function splitBibleGroups(slide,groups){if(!slide||!groups?.length)return;pushHistory();const parts=groups.length,idx=ps.project.slides.indexOf(slide),copies=groups.map((g,i)=>{const n=clone(slide);n.id=uid();n.elements.forEach(e=>e.id=uid());const body=n.elements.find(e=>e.type==='bible'||e.role==='bibleText');if(body)body.text=g.join('\n');const counter=baseElement('text',{x:82,y:92,w:12,h:5,text:`(${toKm(i+1)}/${toKm(parts)})`,fontSize:18,align:'right',valign:'bottom',opacity:.62,role:'pageCounter'});n.elements=n.elements.filter(e=>e.role!=='pageCounter');n.elements.push(counter);return n});ps.project.slides.splice(idx,1,...copies);ps.slideId=copies[0].id;ps.slideAnchorId=ps.slideId;ps.selectedSlides=new Set([ps.slideId]);ps.elementId=null;ps.selectedElements.clear();dirty(true)}
