async function measureSlideFit(slide){if(!slide)return new Map();const stage=document.createElement('div');stage.className='psn-fit-measure';stage.style.width=(ps.project?.ratio==='4:3'?720:960)+'px';stage.style.height='540px';stage.style.background=slide.background||ps.project?.master?.bg||'#07110d';stage.innerHTML=(slide.elements||[]).sort((a,b)=>(a.z||1)-(b.z||1)).map(e=>`<div class="psn-canvas-el" data-el="${esc(e.id)}" style="${elStyle(e)}${e.type==='shape'?`;background:${esc(e.fill||ps.project?.master?.accent||'#59e9ae')};border-radius:${Number(e.radius)||0}px`:e.fill&&e.fill!=='transparent'?`;background:${esc(e.fill)}`:''}"><div class="psn-el-content">${elementInner(e)}</div></div>`).join('');document.body.appendChild(stage);try{if(document.fonts?.ready)await document.fonts.ready;fitTextElements(stage,slide);return new Map([...stage.querySelectorAll('[data-el]')].map(n=>[n.dataset.el,Number(n.dataset.fitPx)||0]))}finally{stage.remove()}}
async function autoSplitBibleSlide(){const slide=currentSlide(),rows=verseRows(slide),body=slide?.elements?.find(e=>e.type==='bible'||e.role==='bibleText');if(!slide||!body||rows.length<2)return toast('Not enough Bible verses to split');const authored=Math.max(8,Number(body.fontSize)||32),minGood=Math.max(18,authored*.78),maxParts=Math.min(rows.length,12);for(let parts=1;parts<=maxParts;parts++){const groups=balancedVerseGroups(rows,parts);let ok=true;for(const g of groups){const test=clone(slide),b=test.elements.find(e=>e.type==='bible'||e.role==='bibleText');b.text=g.join('\n');const fits=await measureSlideFit(test),px=fits.get(b.id)||0;if(px<minGood){ok=false;break}}if(ok){if(parts===1)return toast('This slide already fits well');splitBibleGroups(slide,groups);toast(`Best fit: ${parts} slides`);return}}splitBibleGroups(slide,balancedVerseGroups(rows,maxParts));toast(`Best fit: ${maxParts} slides`)}

