function bibleSlide(ref,text,part=''){const s=makeSlide(false);s.name='Bible';s.elements=[baseElement('text',{x:7,y:7,w:86,h:12,text:ref,fontFamily:ps.project.master.titleFont,fontSize:42,bold:true,color:ps.project.master.accent,align:'center',z:10,role:'bibleRef'}),baseElement('text',{x:7,y:21,w:86,h:67,text,fontFamily:ps.project.master.bodyFont,fontSize:text.length>650?42:text.length>420?48:text.length>240?54:60,color:ps.project.master.fg,align:'left',valign:'center',lineHeight:1.42,z:10,role:'bibleText'})];if(part)s.elements.push(baseElement('text',{x:83,y:92,w:12,h:5,text:part,fontSize:18,align:'right',valign:'bottom',opacity:.62,role:'pageCounter'}));return s}
function splitPassageRows(p){const out=[];let cur=[],chars=0;for(const r of p.rows){const line=`${toKm(r.v)} ${r.text}`;if(cur.length&&(cur.length>=4||chars+line.length>560)){out.push(cur);cur=[];chars=0}cur.push(line);chars+=line.length}if(cur.length)out.push(cur);return out}
async function smartSlides(input){await loadBible();const lines=input.replace(/\r/g,'').split('\n'),out=[],warn=[];let buf=[];const flush=()=>{const a=buf.map(x=>x.trim()).filter(Boolean);if(a.length){out.push(textSlide(a.length>1?a[0]:'',a.length>1?a.slice(1).join('\n'):a[0]));buf=[]}};for(const raw of lines){const line=raw.trim();if(!line){flush();continue}if(parseRef(line)){flush();try{const p=await passage(line),parts=splitPassageRows(p);parts.forEach((rows,i)=>out.push(bibleSlide(p.reference,rows.join('\n'),parts.length>1?`(${toKm(i+1)}/${toKm(parts.length)})`:'')))}catch(e){warn.push(e.message)}continue}if(/^ចំណងជើង\s*[:：]/.test(line)||/ព្រះបន្ទូល.*ម៉ោង/.test(line)){flush();out.push(titleSlide(line.replace(/^ចំណងជើង\s*[:：]\s*/,'')));continue}buf.push(line)}flush();return{slides:out,warn}}
async function runSmart(replace){const input=$('#psnSmartInput')?.value.trim(),st=$('#psnSmartStatus');if(!input)return;if(st)st.textContent='Reading Bible1954…';try{const g=await smartSlides(input);if(!g.slides.length)throw Error('No slide content found');pushHistory();if(replace)ps.project.slides=g.slides;else ps.project.slides.push(...g.slides);ps.slideId=(replace?ps.project.slides[0]:g.slides[0]).id;ps.selectedSlides=new Set([ps.slideId]);ps.elementId=null;ps.selectedElements.clear();ps.toolMode='slides';dirty(true);toast(`Generated ${g.slides.length} slides`);if(st)st.textContent=g.warn.length?g.warn.join(' · '):`Generated ${g.slides.length} slides`}catch(e){if(st)st.textContent=e.message}}
function renderBibleProperties(body){body.innerHTML=`<section class="psn-props-section"><h4>Bible1954</h4><div class="psn-field"><span>Reference</span><input id="psnBibleRef" placeholder="អេភេសូរ 6:1-4"></div><div class="psn-bible-preview" id="psnBiblePreview">Enter a reference to preview.</div><button class="psn-prop-btn active" id="psnInsertBible" style="width:100%;margin-top:8px"><i class="ri-book-open-line"></i> Insert Bible Passage</button></section>`;const inp=$('#psnBibleRef'),pre=$('#psnBiblePreview');let t;inp.oninput=()=>{clearTimeout(t);t=setTimeout(async()=>{if(!inp.value.trim())return;try{const p=await passage(inp.value.trim());pre.textContent=`${p.reference} — ${p.text.slice(0,220)}${p.text.length>220?'…':''}`}catch{pre.textContent='Reference not recognized'}},220)};$('#psnInsertBible').onclick=async()=>{if(await addBibleRef(inp.value.trim())){ps.toolMode='object';renderProperties()}}}
function renderDesignProperties(body){body.innerHTML=`<section class="psn-props-section"><h4>Design</h4><div class="psn-field"><span>Ratio</span><select id="psnDesignRatio"><option value="16:9"${ps.project.ratio==='16:9'?' selected':''}>16:9 Widescreen</option><option value="4:3"${ps.project.ratio==='4:3'?' selected':''}>4:3 Standard</option></select></div><div class="psn-inline"><label class="psn-field"><span>Background</span><input id="psnDesignBg" type="color" value="${esc(ps.project.master.bg.slice(0,7))}"></label><label class="psn-field"><span>Text</span><input id="psnDesignFg" type="color" value="${esc(ps.project.master.fg.slice(0,7))}"></label><label class="psn-field"><span>Accent</span><input id="psnDesignAccent" type="color" value="${esc(ps.project.master.accent.slice(0,7))}"></label></div><div class="psn-field"><span>Title Font</span><select id="psnDesignTitleFont">${fontOptions(ps.project.master.titleFont)}</select></div><div class="psn-field"><span>Body Font</span><select id="psnDesignBodyFont">${fontOptions(ps.project.master.bodyFont)}</select></div><button class="psn-prop-btn active" id="psnApplyDesign" style="width:100%">Apply Design to Project</button></section>`;$('#psnApplyDesign').onclick=()=>{pushHistory();ps.project.ratio=$('#psnDesignRatio').value;ps.project.master.bg=$('#psnDesignBg').value;ps.project.master.fg=$('#psnDesignFg').value;ps.project.master.accent=$('#psnDesignAccent').value;ps.project.master.titleFont=$('#psnDesignTitleFont').value;ps.project.master.bodyFont=$('#psnDesignBodyFont').value;for(const sl of ps.project.slides){if(!sl.background){}for(const e of sl.elements){if(e.role==='title'||e.role==='subtitle'||e.role==='bibleRef')e.fontFamily=ps.project.master.titleFont;else if(['text','bible'].includes(e.type))e.fontFamily=ps.project.master.bodyFont}}dirty(true);resetFit()}}
function renderGridProperties(body){body.innerHTML=`<section class="psn-props-section"><h4>Grid</h4><label class="psn-check"><input id="psnGridToggle" type="checkbox"${ps.grid?' checked':''}><span>Show grid</span></label><div class="psn-field"><span>Grid spacing</span><input id="psnGridSize" type="range" min="12" max="80" value="${ps.gridSize}"></div><div class="psn-props-empty compact">Grid is visual only. Object positioning remains freeform.</div></section>`;$('#psnGridToggle').onchange=e=>{ps.grid=e.target.checked;persist();renderCanvas();updateToolbarStates()};$('#psnGridSize').oninput=e=>{ps.gridSize=+e.target.value;persist();renderCanvas()}}

function dirty(full=false,save=true){if(!ps.project)return;ps.project.updatedAt=Date.now();updateSaveState('Saving…');if(full)renderAll();else{renderSlides();renderCanvas()}if(save){clearTimeout(ps.saveTimer);ps.saveTimer=setTimeout(saveProject,520)}}
function updateSaveState(t){const e=$('#psnSaveState');if(e)e.innerHTML=`<i class="${t.startsWith('Saving')?'ri-loader-4-line':'ri-checkbox-circle-fill'}"></i>${esc(t)}`}
async function saveProject(){if(!ps.project)return;clearTimeout(ps.saveTimer);ps.saveTimer=null;try{ps.project.updatedAt=Date.now();await powerslideFinderUpsert(ps.project);const i=ps.projects.findIndex(p=>p.id===ps.project.id);if(i>=0)ps.projects[i]=clone(ps.project);else ps.projects.unshift(clone(ps.project));updateSaveState('Saved · Sync')}catch(err){console.warn('PowerSlide Next save',err);updateSaveState('Saved local');toast(err.message||'PowerSlide save failed')}}
async function loadProjects(){if(ps.loading)return;ps.loading=true;updateSaveState('Loading…');try{const data=await powerslideFinderList();ps.projects=(data?.projects||[]).filter(p=>p?.id&&!p._deleted).map(normalizeProject).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));updateSaveState('Ready');showRecent()}catch(err){console.warn(err);ps.projects=[];updateSaveState('Local mode');showRecent();toast('PowerSlide opened in local mode')}finally{ps.loading=false}}
function openProject(p){if(!p)return;hideToolPopup();ps.project=normalizeProject(clone(p));ps.slideId=ps.project.slides[0]?.id||null;ps.slideAnchorId=ps.slideId;ps.selectedSlides=new Set(ps.slideId?[ps.slideId]:[]);ps.elementId=null;ps.selectedElements.clear();ps.history=[];ps.redo=[];ps.toolMode='slide';hideRecent();renderAll();setTimeout(resetFit,50)}
function showNewProject(){ensureOverlays();hideRecent();const m=$('#psnNewProjectModal');if(!m)return;$('#psnNewTitle').value='ព្រះបន្ទូល';$('#psnNewRatio').value='16:9';m.classList.add('open');setTimeout(()=>$('#psnNewTitle')?.select(),30)}
async function newProject(){const title=($('#psnNewTitle')?.value||'ព្រះបន្ទូល').trim()||'ព្រះបន្ទូល',ratio=$('#psnNewRatio')?.value||'16:9',p=makeProject(title,ratio);$('#psnNewProjectModal')?.classList.remove('open');ps.projects.unshift(clone(p));openProject(p);await saveProject()}
async function closeProject(){hideToolPopup();if(ps.project)await saveProject();ps.project=null;ps.slideId=null;ps.selectedSlides.clear();ps.elementId=null;ps.selectedElements.clear();renderSlides();renderCanvas();showRecent()}

function ensureOverlays(){if($('#psnRecentModal'))return;document.body.insertAdjacentHTML('beforeend',`<div class="psn-modal" id="psnRecentModal"><div class="psn-modal-card psn-recent-card"><div class="psn-modal-head"><strong>Recent Projects</strong><button data-psn-modal-close="recent"><i class="ri-close-line"></i></button></div><div class="psn-recent-list" id="psnRecentList"></div><div class="psn-modal-foot"><button class="psn-primary" id="psnRecentNew"><i class="ri-add-line"></i> New Project</button></div></div></div><div class="psn-modal" id="psnNewProjectModal"><div class="psn-modal-card psn-new-card"><div class="psn-modal-head"><strong>New Project</strong><button data-psn-modal-close="new"><i class="ri-close-line"></i></button></div><div class="psn-new-body"><label class="psn-field"><span>File name</span><input id="psnNewTitle" value="ព្រះបន្ទូល"></label><label class="psn-field"><span>Slide size</span><select id="psnNewRatio"><option value="16:9">16:9 · Widescreen</option><option value="4:3">4:3 · Standard</option></select></label><div class="psn-ratio-preview"><div class="psn-ratio-card wide"><span>16:9</span></div><div class="psn-ratio-card standard"><span>4:3</span></div></div></div><div class="psn-modal-foot"><button class="psn-primary" id="psnCreateProject"><i class="ri-add-line"></i> Create</button></div></div></div><div class="psn-context hidden" id="psnSlideMenu"></div><div class="psn-context hidden" id="psnProjectMenu"></div><div class="psn-export-menu hidden" id="psnExportMenu"><button data-export="pptx"><i class="ri-file-ppt-2-line"></i> Export PPTX</button><button data-export="json"><i class="ri-file-code-line"></i> Export Project JSON</button></div><div class="psn-presenter hidden" id="psnPresenter"><div class="psn-present-stage-shell"><div class="psn-present-stage" id="psnPresentStage"></div></div><div class="psn-present-controls"><button id="psnPresentPrev"><i class="ri-arrow-left-line"></i></button><span id="psnPresentCount"></span><button id="psnPresentNext"><i class="ri-arrow-right-line"></i></button><button id="psnPresentBlack">B</button><button id="psnPresentExit"><i class="ri-close-line"></i></button></div><div class="psn-present-black hidden" id="psnPresentBlackout"></div></div><input id="psnImageInput" type="file" accept="image/*" hidden>`);$('#psnRecentNew').onclick=showNewProject;$('#psnCreateProject').onclick=newProject;document.querySelector('[data-psn-modal-close="recent"]')?.addEventListener('click',()=>{if(ps.project)hideRecent();else close()});document.querySelector('[data-psn-modal-close="new"]')?.addEventListener('click',()=>{$('#psnNewProjectModal')?.classList.remove('open');showRecent()});$('#psnRecentList').onclick=async e=>{const del=e.target.closest('[data-project-delete]');if(del){e.preventDefault();e.stopPropagation();return deleteProjectById(del.dataset.projectDelete)}const b=e.target.closest('[data-project]');if(!b)return;openProject(ps.projects.find(p=>p.id===b.dataset.project))};$('#psnRecentList').oncontextmenu=e=>{const b=e.target.closest('[data-project]');if(!b)return;e.preventDefault();showProjectMenu(e.clientX,e.clientY,b.dataset.project)};$('#psnImageInput').onchange=e=>{const f=e.target.files?.[0];if(f){const cur=currentElement();if(cur?.type==='image'){const r=new FileReader();r.onload=()=>{pushHistory();cur.data=r.result;dirty(true)};r.readAsDataURL(f)}else addImageFile(f)}e.target.value=''};$('#psnPresentPrev').onclick=()=>stepPresent(-1);$('#psnPresentNext').onclick=()=>stepPresent(1);$('#psnPresentBlack').onclick=()=>{ps.present.black=!ps.present.black;$('#psnPresentBlackout').classList.toggle('hidden',!ps.present.black)};$('#psnPresentExit').onclick=stopPresent;$('#psnExportMenu').onclick=e=>{const b=e.target.closest('[data-export]');if(!b)return;hideMenus();b.dataset.export==='pptx'?exportPptx():exportJSON()};document.addEventListener('pointerdown',e=>{if(!e.target.closest('.psn-context,.psn-export-menu,.psn-tool-popover'))hideMenus()})}
async function deleteProjectById(id){const p=ps.projects.find(q=>q.id===id);if(!p||!confirm(`Delete ${projectFileName(p)}?`))return;await powerslideFinderDelete(id);ps.projects=ps.projects.filter(q=>q.id!==id);if(ps.project?.id===id){ps.project=null;ps.slideId=null;ps.selectedSlides.clear();renderAll()}showRecent()}
function showRecent(){ensureOverlays();const list=$('#psnRecentList');list.innerHTML=ps.projects.length?ps.projects.map(p=>`<div class="psn-recent-row"><button class="psn-recent-file" data-project="${esc(p.id)}"><i class="ri-file-ppt-2-line"></i><span>${esc(projectFileName(p))}</span></button><button class="psn-recent-delete" data-project-delete="${esc(p.id)}" title="Delete"><i class="ri-delete-bin-6-line"></i></button></div>`).join(''):`<div class="psn-props-empty">No recent projects.</div>`;$('#psnRecentModal').classList.add('open')}
function hideRecent(){$('#psnRecentModal')?.classList.remove('open')}
function hideMenus(){$$('.psn-context,.psn-export-menu').forEach(x=>x.classList.add('hidden'))}
function positionMenu(m,x,y){m.classList.remove('hidden');const r=m.getBoundingClientRect();m.style.left=clamp(x,6,innerWidth-r.width-6)+'px';m.style.top=clamp(y,6,innerHeight-r.height-6)+'px'}
function showSlideMenu(x,y,id){if(!ps.selectedSlides.has(id))selectSlideOnly(id);const rows=verseRows(currentSlide()).length,m=$('#psnSlideMenu');m.innerHTML=`<button data-slide-cmd="duplicate"><i class="ri-file-copy-line"></i> Duplicate</button><button data-slide-cmd="new"><i class="ri-add-line"></i> New Slide After</button><hr><button data-slide-cmd="up"><i class="ri-arrow-up-line"></i> Move Up</button><button data-slide-cmd="down"><i class="ri-arrow-down-line"></i> Move Down</button><hr><button data-slide-cmd="split2"${rows<2?' disabled':''}>Split Bible → 2 slides</button><button data-slide-cmd="split3"${rows<3?' disabled':''}>Split Bible → 3 slides</button><button data-slide-cmd="splitAuto"${rows<2?' disabled':''}>Auto Split · Best Fit</button><hr><button class="danger" data-slide-cmd="delete"><i class="ri-delete-bin-6-line"></i> Delete</button>`;m.onclick=e=>{const b=e.target.closest('[data-slide-cmd]');if(!b||b.disabled)return;hideMenus();({duplicate:duplicateSlides,new:()=>addSlide(ps.slideId),up:()=>moveSelectedSlides(-1),down:()=>moveSelectedSlides(1),split2:()=>splitBibleSlide(2),split3:()=>splitBibleSlide(3),splitAuto:autoSplitBibleSlide,delete:deleteSlides})[b.dataset.slideCmd]?.()};positionMenu(m,x,y)}
function showProjectMenu(x,y,id){const p=ps.projects.find(q=>q.id===id),m=$('#psnProjectMenu');if(!p)return;m.innerHTML=`<button data-pcmd="open">Open</button><button data-pcmd="rename">Rename</button><button data-pcmd="duplicate">Duplicate</button><button data-pcmd="export">Export JSON</button><hr><button class="danger" data-pcmd="delete">Delete</button>`;m.onclick=async e=>{const b=e.target.closest('[data-pcmd]');if(!b)return;hideMenus();if(b.dataset.pcmd==='open')openProject(p);if(b.dataset.pcmd==='rename'){const n=(prompt('Rename project',p.title)||'').trim();if(n){p.title=n;p.updatedAt=Date.now();await powerslideFinderUpsert(p);showRecent()}}if(b.dataset.pcmd==='duplicate'){const n=clone(p);n.id=uid();n.title=p.title+' Copy';n.createdAt=n.updatedAt=Date.now();n.slides.forEach(s=>{s.id=uid();s.elements.forEach(e=>e.id=uid())});ps.projects.unshift(n);await powerslideFinderUpsert(n);showRecent()}if(b.dataset.pcmd==='export')exportJSON(p);if(b.dataset.pcmd==='delete'){if(confirm(`Delete ${projectFileName(p)}?`)){await powerslideFinderDelete(p.id);ps.projects=ps.projects.filter(q=>q.id!==p.id);showRecent()}}};positionMenu(m,x,y)}

function toolIcon(key,fallback){const state=window.TahoeAdmin?.state?.()||{},custom=state.inlineIcons?.[`powerslide-next.toolbar.${key}`];return custom||`<i class="${fallback}"></i>`}
const TOOLS=[['sidebar','Sidebar','ri-layout-left-line','primary'],['slides','Slides','ri-menu-2-line','primary'],['smart','Smart Generate','ri-sparkling-2-line','primary'],['text','Text','ri-text','primary'],['bible','Bible','ri-book-open-line','primary'],['image','Image','ri-image-line','secondary'],['shape','Shape','ri-add-box-line','secondary'],['design','Design','ri-palette-line','secondary'],['grid','Grid','ri-grid-line','secondary'],['duplicate','Duplicate','ri-file-copy-line','secondary'],['delete','Delete','ri-delete-bin-6-line','secondary'],['properties','Properties','ri-equalizer-2-line','primary']];
function renderTools(){const bar=$('#psnToolsbar');if(!bar)return;bar.innerHTML=`<button class="psn-tool-grip" data-toolbar-grip title="Drag toolbar"><i class="ri-drag-move-2-line"></i></button>`+TOOLS.map(([k,l,i,grp])=>`<button class="psn-tool ${grp}" data-tool="${k}" title="${esc(l)}"><span class="psn-tool-icon" data-icon-key="${k}" data-direct-icon-scope="inline" data-direct-icon-key="powerslide-next.toolbar.${k}" data-direct-icon-label="PowerSlide ${esc(l)} icon" data-direct-icon-base="${esc(`<i class='${i}'></i>`)}"><span class="icon-glyph">${toolIcon(k,i)}</span></span><span class="psn-tool-label">${esc(l)}</span></button>`).join('')+`<span class="psn-tool-sep"></span><span class="psn-verse-label">¹ Verse:</span><button class="psn-tool primary" data-tool="verse"><span class="psn-tool-label" id="psnVerseLabel">Normal</span></button><button class="psn-tool psn-more" data-tool="more"><i class="ri-more-2-fill"></i></button><div class="psn-more-menu hidden" id="psnMoreMenu"></div>`;positionToolbar();prepareToolCustomizers();bindToolbarDrag();updateToolbarStates()}
function prepareToolCustomizers(){let customizing=false,owner=false;try{customizing=document.querySelector('.window')?.classList.contains('customizing');owner=typeof isOwnerAdmin==='function'&&isOwnerAdmin()}catch{}$$('#psnToolsbar .psn-tool-icon').forEach(el=>{el.querySelector('.psn-tool-icon-edit')?.remove();if(!customizing||!owner)return;const b=document.createElement('button');b.type='button';b.className='psn-tool-icon-edit';b.innerHTML='<i class="ri-edit-2-line"></i>';b.onclick=e=>{e.preventDefault();e.stopPropagation();try{openDirectIconEditor(el,e.clientX,e.clientY)}catch{toast('Open Admin Customize Mode to edit this icon')}};el.append(b)})}
function updateToolbarStates(){const bar=$('#psnToolsbar');if(!bar)return;bar.querySelector('[data-tool="grid"]')?.classList.toggle('active',ps.grid);bar.querySelector('[data-tool="properties"]')?.classList.toggle('active',props.classList.contains('open'));bar.querySelector('[data-tool="sidebar"]')?.classList.toggle('active',ps.sidebarOpen);const v=$('#psnVerseLabel');if(v)v.textContent=ps.project?.master?.verseNumberStyle==='superscript'?'Superscript':'Normal'}
function setToolMode(mode){ps.toolMode=mode;renderProperties()}
function runTool(k,anchor=null){if(k==='sidebar'){ps.sidebarOpen=!ps.sidebarOpen;app.classList.toggle('sidebar-hidden',!ps.sidebarOpen);persist();fitCanvas();updateToolbarStates();return}if(!ps.project&&k!=='properties')return showRecent();if(k==='slides'){setToolMode('slides');showToolPopup('slides',anchor)}if(k==='smart'){setToolMode('smart');showToolPopup('smart',anchor)}if(k==='text'){addText();setToolMode('object');showToolPopup('text',anchor)}if(k==='bible'){ps.elementId=null;ps.selectedElements.clear();setToolMode('bible');showToolPopup('bible',anchor)}if(k==='image'){showToolPopup('image',anchor)}if(k==='shape'){addShape();setToolMode('object');showToolPopup('shape',anchor)}if(k==='design'){setToolMode('design');showToolPopup('design',anchor)}if(k==='verse'){pushHistory();ps.project.master.verseNumberStyle=ps.project.master.verseNumberStyle==='superscript'?'normal':'superscript';dirty(true);showToolPopup('verse',anchor)}if(k==='grid'){ps.grid=!ps.grid;persist();ps.toolMode='grid';renderCanvas();showToolPopup('grid',anchor);updateToolbarStates()}if(k==='duplicate'){currentElement()?duplicateElement():duplicateSlides()}if(k==='delete'){currentElement()?deleteElements():deleteSlides()}if(k==='properties')toggleProps();if(k==='more')toggleMore()}
function showToolPopup(kind,anchor){const box=$('#psnToolPopover'),body=$('#psnToolPopoverBody'),title=$('#psnToolPopoverTitle');if(!box||!body||!ps.project)return;title.textContent=TOOLS.find(x=>x[0]===kind)?.[1]||kind;body.innerHTML='';if(kind==='smart')renderSmartProperties(body);else if(kind==='bible')renderBibleProperties(body);else if(kind==='design')renderDesignProperties(body);else if(kind==='grid')renderGridProperties(body);else if(kind==='slides')renderToolSlides(body);else if(kind==='text')renderToolText(body);else if(kind==='image')renderToolImage(body);else if(kind==='shape')renderToolShape(body);else if(kind==='verse')renderToolVerse(body);else return;box.classList.remove('hidden');positionToolPopup(anchor)}
function hideToolPopup(){$('#psnToolPopover')?.classList.add('hidden')}
function positionToolPopup(anchor){const box=$('#psnToolPopover'),work=$('#psnWorkspace');if(!box||!work||box.classList.contains('hidden'))return;const wr=work.getBoundingClientRect(),ar=(anchor||$('#psnToolsbar')).getBoundingClientRect(),br=box.getBoundingClientRect();let x=clamp(ar.left-wr.left,8,Math.max(8,wr.width-br.width-8)),y=clamp(ar.bottom-wr.top+8,8,Math.max(8,wr.height-br.height-8));box.style.left=x+'px';box.style.top=y+'px'}
function renderToolSlides(body){body.innerHTML=`<div class="psn-tool-card"><button class="psn-prop-btn active" id="psnToolNewSlide">+ New Slide</button><button class="psn-prop-btn" id="psnToolDupSlide">Duplicate</button><button class="psn-prop-btn danger" id="psnToolDelSlide">Delete</button></div>`;$('#psnToolNewSlide').onclick=()=>addSlide(ps.slideId);$('#psnToolDupSlide').onclick=duplicateSlides;$('#psnToolDelSlide').onclick=deleteSlides}
function renderToolText(body){const e=currentElement();body.innerHTML=`<div class="psn-tool-card"><div class="psn-field"><span>Font</span><select id="psnToolFont">${fontOptions(e?.fontFamily||ps.project.master.bodyFont)}</select></div><div class="psn-inline"><label class="psn-field"><span>Size</span><input id="psnToolSize" type="number" min="8" max="200" value="${Number(e?.fontSize)||42}"></label><button class="psn-prop-btn active" id="psnToolAddText">+ Text</button></div></div>`;$('#psnToolAddText').onclick=addText;$('#psnToolFont').onchange=x=>{const cur=currentElement();if(cur){cur.fontFamily=x.target.value;dirty(true)}};$('#psnToolSize').oninput=x=>{const cur=currentElement();if(cur){cur.fontSize=+x.target.value;dirty()}}}
function renderToolImage(body){body.innerHTML=`<div class="psn-tool-card"><button class="psn-prop-btn active" id="psnToolChooseImage" style="width:100%"><i class="ri-image-add-line"></i> Choose Image</button><div class="psn-props-empty compact">Select an image object to access full image controls in Properties.</div></div>`;$('#psnToolChooseImage').onclick=()=>$('#psnImageInput')?.click()}
