function renderToolVerse(body){body.innerHTML=`<div class="psn-tool-card"><div class="psn-field"><span>Verse number style</span><select id="psnToolVerseStyle"><option value="normal"${ps.project.master.verseNumberStyle!=='superscript'?' selected':''}>Normal</option><option value="superscript"${ps.project.master.verseNumberStyle==='superscript'?' selected':''}>Superscript</option></select></div></div>`;$('#psnToolVerseStyle').onchange=x=>{pushHistory();ps.project.master.verseNumberStyle=x.target.value;dirty(true);updateToolbarStates()}}
function toggleMore(){const m=$('#psnMoreMenu');if(!m)return;const nowHidden=m.classList.toggle('hidden');if(nowHidden)return;const mb=$('#psnToolsbar [data-tool="more"]'),r=mb?.getBoundingClientRect();if(r){m.style.left=Math.max(6,r.right-180)+'px';m.style.top=(r.bottom+6)+'px'}const hidden=TOOLS.filter(([k])=>{const b=$(`#psnToolsbar [data-tool="${k}"]`);return b&&getComputedStyle(b).display==='none'});m.innerHTML=hidden.map(([k,l,i])=>`<button data-more-tool="${k}"><i class="${i}"></i>${esc(l)}</button>`).join('');m.querySelectorAll('[data-more-tool]').forEach(b=>b.onclick=()=>{m.classList.add('hidden');runTool(b.dataset.moreTool)})}
function updateToolResponsiveness(){const main=app.querySelector('.psn-main'),w=main?.clientWidth||0;app.classList.toggle('psn-compact',w<980);app.classList.toggle('psn-tiny',w<720)}

function positionToolbar(){const bar=$('#psnToolsbar'),work=$('#psnWorkspace');if(!bar||!work)return;const maxX=Math.max(8,work.clientWidth-bar.offsetWidth-8),maxY=Math.max(8,work.clientHeight-bar.offsetHeight-8);ps.toolbar.x=clamp(Number(ps.toolbar.x)||14,8,maxX);ps.toolbar.y=clamp(Number(ps.toolbar.y)||12,8,maxY);bar.style.left=ps.toolbar.x+'px';bar.style.top=ps.toolbar.y+'px';bar.style.right='auto'}
