function positionProps(){if(!props.classList.contains('open')||innerWidth<=760)return;const r=app.getBoundingClientRect(),pr=props.getBoundingClientRect();if(ps.props.dx==null)ps.props.dx=r.width+14;let left=r.left+ps.props.dx,top=r.top+(ps.props.dy??82);left=clamp(left,6,Math.max(6,innerWidth-pr.width-6));top=clamp(top,6,Math.max(6,innerHeight-pr.height-6));props.style.left=Math.round(left)+'px';props.style.top=Math.round(top)+'px';props.style.right='auto';props.style.bottom='auto'}
