function focus(){try{focusTahoeWindow(app)}catch{app.style.zIndex='80'}props.style.zIndex=String((Number(app.style.zIndex)||80)+1)}
async function open(){if(!canOpen())return toast('Pro access required');ensureOverlays();await Promise.all([loadFonts(),loadBible()]);restoreWindow();app.classList.add('open');app.classList.toggle('sidebar-hidden',!ps.sidebarOpen);arrangeDefaultPair();launcher.classList.add('active');updateProfile();focus();toggleProps(ps.props.open!==false);renderTools();positionToolbar();updateToolResponsiveness();if(!ps.openedOnce){ps.openedOnce=true;await loadProjects()}else if(ps.project){renderAll();requestAnimationFrame(fitCanvas)}else showRecent();setTimeout(positionProps,20)}
