function bindWindowMotion(){let drag=null,split=null,resize=null;const surfaces=[$('#psnSidebarTop'),$('#psnToolbar'),...$$('[data-psn-drag-edge]')];const start=(e,s)=>{if(innerWidth<=760||e.target.closest('button,input,textarea,select,[data-no-drag]'))return;const r=pixelizeWindow();drag={id:e.pointerId,dx:e.clientX-r.left,dy:e.clientY-r.top};s.setPointerCapture(e.pointerId);app.classList.add('dragging');focus()};const move=e=>{if(!drag||e.pointerId!==drag.id)return;const r=app.getBoundingClientRect();app.style.left=clamp(e.clientX-drag.dx,0,Math.max(0,innerWidth-r.width))+'px';app.style.top=clamp(e.clientY-drag.dy,0,Math.max(0,innerHeight-r.height))+'px';positionProps()};const end=e=>{if(!drag||e.pointerId!==drag.id)return;drag=null;app.classList.remove('dragging');saveWindow();positionProps()};surfaces.filter(Boolean).forEach(s=>{s.addEventListener('pointerdown',e=>start(e,s));s.addEventListener('pointermove',move);s.addEventListener('pointerup',end);s.addEventListener('pointercancel',end)});const sp=$('#psnSplitter');sp?.addEventListener('pointerdown',e=>{if(innerWidth<=760)return;split={id:e.pointerId,x:e.clientX,w:ps.sidebar};sp.setPointerCapture(e.pointerId);sp.classList.add('active')});sp?.addEventListener('pointermove',e=>{if(!split||e.pointerId!==split.id)return;ps.sidebar=clamp(Math.round(split.w+e.clientX-split.x),190,430);app.style.setProperty('--psn-sidebar',ps.sidebar+'px');fitCanvas();scaleThumbs()});const es=e=>{if(!split||e.pointerId!==split.id)return;split=null;sp.classList.remove('active');persist();fitCanvas();scaleThumbs()};sp?.addEventListener('pointerup',es);sp?.addEventListener('pointercancel',es);$$('[data-psn-resize]').forEach(h=>{h.addEventListener('pointerdown',e=>{if(innerWidth<=760)return;e.stopPropagation();const r=pixelizeWindow();resize={id:e.pointerId,dir:h.dataset.psnResize,x:e.clientX,y:e.clientY,l:r.left,t:r.top,w:r.width,h:r.height};h.setPointerCapture(e.pointerId);app.classList.add('resizing');focus()});h.addEventListener('pointermove',e=>{if(!resize||e.pointerId!==resize.id)return;const c=resize,dx=e.clientX-c.x,dy=e.clientY-c.y;let l=c.l,t=c.t,w=c.w,hg=c.h;if(c.dir.includes('e'))w=Math.max(720,c.w+dx);if(c.dir.includes('s'))hg=Math.max(500,c.h+dy);if(c.dir.includes('w')){w=Math.max(720,c.w-dx);l=c.l+(c.w-w)}if(c.dir.includes('n')){hg=Math.max(500,c.h-dy);t=c.t+(c.h-hg)}w=Math.min(w,innerWidth-l);hg=Math.min(hg,innerHeight-t);Object.assign(app.style,{left:l+'px',top:t+'px',width:w+'px',height:hg+'px'});fitCanvas();scaleThumbs();positionProps();positionToolbar();positionToolPopup();updateToolResponsiveness()});const er=e=>{if(!resize||e.pointerId!==resize.id)return;resize=null;app.classList.remove('resizing');saveWindow();fitCanvas();scaleThumbs();positionProps();positionToolbar();positionToolPopup();updateToolResponsiveness()};h.addEventListener('pointerup',er);h.addEventListener('pointercancel',er)})}
function bindPropsDrag(){const head=$('#psnPropsHead');let d=null;head?.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;const r=props.getBoundingClientRect();d={id:e.pointerId,dx:e.clientX-r.left,dy:e.clientY-r.top};head.setPointerCapture(e.pointerId);focus()});head?.addEventListener('pointermove',e=>{if(!d||e.pointerId!==d.id)return;const pr=props.getBoundingClientRect(),left=clamp(e.clientX-d.dx,4,Math.max(4,innerWidth-pr.width-4)),top=clamp(e.clientY-d.dy,4,Math.max(4,innerHeight-pr.height-4));props.style.left=left+'px';props.style.top=top+'px';const ar=app.getBoundingClientRect();ps.props.dx=left-ar.left;ps.props.dy=top-ar.top});const end=e=>{if(!d||e.pointerId!==d.id)return;d=null;persist()};head?.addEventListener('pointerup',end);head?.addEventListener('pointercancel',end);new ResizeObserver(()=>{if(!props.classList.contains('open'))return;const r=props.getBoundingClientRect();ps.props.w=Math.round(r.width);ps.props.h=Math.round(r.height);persist()}).observe(props)}
function bindStagePan(){const sc=$('#psnStageScroll');if(!sc)return;sc.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();setZoom(ps.zoom*(e.deltaY>0?.9:1.1))}},{passive:false});sc.addEventListener('pointerdown',e=>{if(!(ps.space||e.button===1))return;e.preventDefault();ps.pan={id:e.pointerId,x:e.clientX,y:e.clientY,l:sc.scrollLeft,t:sc.scrollTop};sc.setPointerCapture(e.pointerId);sc.classList.add('panning')});sc.addEventListener('pointermove',e=>{if(!ps.pan||e.pointerId!==ps.pan.id)return;sc.scrollLeft=ps.pan.l-(e.clientX-ps.pan.x);sc.scrollTop=ps.pan.t-(e.clientY-ps.pan.y)});const end=e=>{if(!ps.pan||e.pointerId!==ps.pan.id)return;ps.pan=null;sc.classList.remove('panning')};sc.addEventListener('pointerup',end);sc.addEventListener('pointercancel',end)}

function beginElementDrag(e,node){if(e.target.closest('[contenteditable=true]'))return;const el=currentSlide()?.elements.find(x=>x.id===node.dataset.el);if(!el)return;if(e.metaKey||e.ctrlKey){selectElement(el.id,true);e.preventDefault();return}if(!ps.selectedElements.has(el.id))selectElement(el.id);pushHistory();const r=$('#psnSlideCanvas').getBoundingClientRect(),mode=e.target.closest('[data-el-resize]')?'resize':e.target.closest('[data-el-rotate]')?'rotate':'move';ps.drag={id:e.pointerId,mode,rect:r,startX:e.clientX,startY:e.clientY,primary:el.id,all:Object.fromEntries([...ps.selectedElements].map(id=>{const x=currentSlide().elements.find(q=>q.id===id);return[id,clone(x)]}))};node.setPointerCapture?.(e.pointerId);e.preventDefault();e.stopPropagation()}
