function endElementDrag(e){if(!ps.drag||ps.drag.id!==e.pointerId)return;ps.drag=null;dirty(true)}
function startInlineEdit(node){const e=currentSlide()?.elements.find(x=>x.id===node.dataset.el);if(!e||!['text','bible'].includes(e.type))return;const c=node.querySelector('.psn-el-content');if(!c)return;c.contentEditable='true';c.spellcheck=false;c.focus({preventScroll:true});node.classList.add('editing');const raw=()=>{if(e.type==='bible'){const div=document.createElement('div');div.innerHTML=c.innerHTML;div.querySelector('.psn-bible-ref')?.remove();return div.innerText}else return c.innerText};const save=()=>{e.text=raw();dirty(false)};c.addEventListener('input',save);c.addEventListener('blur',()=>{c.contentEditable='false';node.classList.remove('editing');fitTextNode(node,e);dirty(true)},{once:true})}

function renderPresent(){const stage=$('#psnPresentStage'),s=ps.project?.slides?.[ps.present.index];if(!stage||!s)return;stage.classList.toggle('ratio43',ps.project.ratio==='4:3');stage.style.background=s.background||ps.project.master.bg;stage.innerHTML=s.elements.sort((a,b)=>(a.z||1)-(b.z||1)).map(e=>`<div class="psn-present-el" data-el="${esc(e.id)}" style="${elStyle(e)}${e.type==='shape'?`;background:${esc(e.fill||ps.project.master.accent)};border-radius:${Number(e.radius)||0}px`:e.fill&&e.fill!=='transparent'?`;background:${esc(e.fill)}`:''}"><div class="psn-el-content">${elementInner(e)}</div></div>`).join('');fitTextElements(stage,s);scheduleTextFit(stage,s);$('#psnPresentCount').textContent=`${ps.present.index+1} / ${ps.project.slides.length}`;fitPresenter()}
function fitPresenter(){const shell=$('.psn-present-stage-shell'),stage=$('#psnPresentStage');if(!shell||!stage||!ps.present.open)return;const w=ps.project.ratio==='4:3'?720:960,h=540,sc=Math.min((innerWidth-80)/w,(innerHeight-80)/h);stage.style.transform=`scale(${Math.max(.1,sc)})`;shell.style.width=w*sc+'px';shell.style.height=h*sc+'px'}
