function loadScript(src){return new Promise((res,rej)=>{if(window.PptxGenJS)return res();const s=document.createElement('script');s.src=src;s.onload=res;s.onerror=rej;document.head.append(s)})}
function hex(v,f='FFFFFF'){const s=String(v||'').trim();return /^#[0-9a-f]{6}$/i.test(s)?s.slice(1).toUpperCase():f}
function pptxBibleRuns(e,fitPt){const runs=[],body=hex(e.color||ps.project.master.fg),accent=hex(ps.project.master.accent,'59E9AE'),sup=ps.project.master.verseNumberStyle==='superscript';if(e.type==='bible'&&e.ref)runs.push({text:e.ref,options:{bold:true,color:accent,fontSize:Math.max(6,fitPt*.62),breakLine:true}});for(const line of String(e.text||'').split(/\n+/).filter(Boolean)){const m=line.match(/^\s*([០-៩0-9]+)\s+(.*)$/);if(m){runs.push({text:m[1],options:{bold:true,color:'FFD84D',superscript:sup,fontSize:fitPt}});runs.push({text:' '+m[2],options:{color:body,fontSize:fitPt,breakLine:true}})}else runs.push({text:line,options:{color:body,fontSize:fitPt,breakLine:true}})}return runs}
async function exportPptx(){if(!ps.project)return;toast('Preparing PPTX…');try{if(!window.PptxGenJS)await loadScript('https://cdn.jsdelivr.net/gh/gitbrent/pptxgenjs@3.12.0/dist/pptxgen.bundle.js');if(document.fonts?.ready)await document.fonts.ready;const pptx=new PptxGenJS();pptx.layout=ps.project.ratio==='4:3'?'LAYOUT_4X3':'LAYOUT_WIDE';pptx.author='Tahoe Powerslide';pptx.title=ps.project.title;const W=ps.project.ratio==='4:3'?10:13.333,H=7.5;for(const s of ps.project.slides){const fits=await measureSlideFit(s),sl=pptx.addSlide();sl.background={color:hex(s.background||ps.project.master.bg,'07110D')};for(const e of [...s.elements].sort((a,b)=>(a.z||1)-(b.z||1))){const x=e.x/100*W,y=e.y/100*H,w=e.w/100*W,h=e.h/100*H,rot=Number(e.rotation)||0,transparency=Math.round((1-(e.opacity??1))*100);if(e.type==='shape'){const type=(Number(e.radius)||0)>0?(pptx.ShapeType.roundRect||pptx.ShapeType.rect):pptx.ShapeType.rect;sl.addShape(type,{x,y,w,h,rotate:rot,fill:{color:hex(e.fill||ps.project.master.accent,'59E9AE'),transparency},line:{transparency:100}})}else if(e.type==='image'&&e.data){sl.addImage({data:e.data,x,y,w,h,rotate:rot,transparency})}else{const fitPx=fits.get(e.id)||Math.max(4,Number(e.fontSize)||32),fitPt=Math.max(3,fitPx),isBible=e.type==='bible'||e.role==='bibleText',text=isBible?pptxBibleRuns(e,fitPt):(e.text||''),opts={x,y,w,h,rotate:rot,fontFace:e.fontFamily||ps.project.master.bodyFont,fontSize:fitPt,bold:!!e.bold,italic:!!e.italic,underline:!!e.underline,color:hex(e.color||ps.project.master.fg),align:e.align||'left',valign:e.valign==='top'?'top':e.valign==='bottom'?'bottom':'mid',margin:0,fit:'shrink',transparency};if(e.fill&&e.fill!=='transparent'&&/^#[0-9a-f]{6}$/i.test(e.fill))opts.fill={color:hex(e.fill),transparency:0};sl.addText(text,opts)}}}await pptx.writeFile({fileName:`${ps.project.date}-${ps.project.title.replace(/[\\/:*?"<>|]/g,'-')}.pptx`});toast('PPTX exported')}catch(e){console.error(e);toast('PPTX export needs internet the first time')}}
function exportJSON(p=ps.project){if(!p)return;const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));a.href=u;a.download=projectFileName(p)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
