function bindUI(){ensureOverlays();app.style.setProperty('--psn-sidebar',ps.sidebar+'px');if(ps.props.w)props.style.width=ps.props.w+'px';if(ps.props.h)props.style.height=ps.props.h+'px';renderTools();$('#psnClose')?.addEventListener('click',close);$('#psnMin')?.addEventListener('click',close);$('#psnZoomWindow')?.addEventListener('click',zoomWindow);$('#psnSearch')?.addEventListener('input',e=>{ps.query=e.target.value;renderSlides()});$('#psnAddSlide')?.addEventListener('click',()=>addSlide(ps.slideId));$('#psnAccount')?.addEventListener('click',()=>{try{window.TahoeAdmin?.restore?.();openPage('account');focusTahoeWindow?.($('#window'))}catch{}});$('#psnSlideList')?.addEventListener('click',e=>{const b=e.target.closest('[data-slide]');if(!b)return;const id=b.dataset.slide;if(e.shiftKey)rangeSelectSlides(id);else if(e.metaKey||e.ctrlKey)toggleSlideSelection(id);else selectSlideOnly(id)});$('#psnSlideList')?.addEventListener('contextmenu',e=>{const b=e.target.closest('[data-slide]');if(!b)return;e.preventDefault();showSlideMenu(e.clientX,e.clientY,b.dataset.slide)});$('#psnSlideList')?.addEventListener('dragstart',e=>{const b=e.target.closest('[data-slide]');if(!b)return;if(!ps.selectedSlides.has(b.dataset.slide))selectSlideOnly(b.dataset.slide);ps.thumbDrag=[...ps.selectedSlides];e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',b.dataset.slide)});$('#psnSlideList')?.addEventListener('dragover',e=>{if(!ps.thumbDrag)return;const b=e.target.closest('[data-slide]');if(b){e.preventDefault();b.classList.add('drop-target')}});$('#psnSlideList')?.addEventListener('dragleave',e=>e.target.closest('[data-slide]')?.classList.remove('drop-target'));$('#psnSlideList')?.addEventListener('drop',e=>{const b=e.target.closest('[data-slide]');if(!b||!ps.thumbDrag)return;e.preventDefault();$$('.drop-target').forEach(x=>x.classList.remove('drop-target'));const r=b.getBoundingClientRect();reorderSlides(b.dataset.slide,e.clientY>r.top+r.height/2);ps.thumbDrag=null});$('#psnSlideList')?.addEventListener('dragend',()=>{ps.thumbDrag=null;$$('.drop-target').forEach(x=>x.classList.remove('drop-target'))});$('#psnSlideCanvas')?.addEventListener('pointerdown',e=>{const n=e.target.closest('[data-el]');if(n)beginElementDrag(e,n);else{ps.elementId=null;ps.selectedElements.clear();ps.toolMode='slide';renderCanvas()}});$('#psnSlideCanvas')?.addEventListener('pointermove',moveElementDrag);$('#psnSlideCanvas')?.addEventListener('pointerup',endElementDrag);$('#psnSlideCanvas')?.addEventListener('pointercancel',endElementDrag);$('#psnSlideCanvas')?.addEventListener('dblclick',e=>{const n=e.target.closest('[data-el]');if(n){e.preventDefault();startInlineEdit(n)}});$('#psnUndoBtn')?.addEventListener('click',undo);$('#psnRedoBtn')?.addEventListener('click',redo);$('#psnFileTitle')?.addEventListener('click',showRecent);$('#psnPropsToggle')?.addEventListener('click',()=>toggleProps());$('#psnFullscreenBtn')?.addEventListener('click',zoomWindow);$('#psnPresentBtn')?.addEventListener('click',startPresent);$('#psnExportBtn')?.addEventListener('click',showExportMenu);$('#psnCloseProjectBtn')?.addEventListener('click',closeProject);$('#psnPropsClose')?.addEventListener('click',()=>toggleProps(false));$('#psnPropsSnap')?.addEventListener('click',snapProps);$('#psnZoomOut')?.addEventListener('click',()=>setZoom(ps.zoom/1.15));$('#psnZoomIn')?.addEventListener('click',()=>setZoom(ps.zoom*1.15));$('#psnZoomFit')?.addEventListener('click',resetFit);$('#psnZoomLabel')?.addEventListener('click',resetFit);$('#psnToolsbar')?.addEventListener('click',e=>{const b=e.target.closest('[data-tool]');if(b&&!e.target.closest('.psn-tool-icon-edit'))runTool(b.dataset.tool,b)});document.addEventListener('keydown',e=>{if(ps.present.open){if(['ArrowRight','PageDown',' '].includes(e.key))stepPresent(1);else if(['ArrowLeft','PageUp'].includes(e.key))stepPresent(-1);else if(e.key==='Escape')stopPresent();else if(e.key.toLowerCase()==='b'){$('#psnPresentBlack').click()}e.preventDefault();return}if(!app.classList.contains('open'))return;if(e.target.matches('input,textarea,select,[contenteditable=true]'))return;if(e.code==='Space'){ps.space=true;$('#psnStageScroll')?.classList.add('pan-ready');e.preventDefault()}if((e.ctrlKey||e.metaKey)&&['+','=','-','_','0'].includes(e.key)){e.preventDefault();e.key==='0'?resetFit():setZoom(ps.zoom*(e.key==='-'||e.key==='_'?1/1.15:1.15))}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();currentElement()?duplicateElement():duplicateSlides()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();exportPptx()}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();currentElement()?deleteElements():deleteSlides()}if(['ArrowRight','ArrowDown'].includes(e.key)&&ps.project&&!currentElement()){const i=ps.project.slides.findIndex(s=>s.id===ps.slideId);selectSlideOnly(ps.project.slides[Math.min(ps.project.slides.length-1,i+1)]?.id)}if(['ArrowLeft','ArrowUp'].includes(e.key)&&ps.project&&!currentElement()){const i=ps.project.slides.findIndex(s=>s.id===ps.slideId);selectSlideOnly(ps.project.slides[Math.max(0,i-1)]?.id)}});document.addEventListener('keyup',e=>{if(e.code==='Space'){ps.space=false;$('#psnStageScroll')?.classList.remove('pan-ready')}});bindWindowMotion();bindPropsDrag();bindStagePan();bindToolbarDrag();$('#psnToolPopoverClose')?.addEventListener('click',hideToolPopup);const ro=new ResizeObserver(()=>{if(app.classList.contains('open')){fitCanvas();scaleThumbs();positionProps();positionToolbar();positionToolPopup();updateToolResponsiveness()}});ro.observe($('#psnWorkspace'));ro.observe(app);ro.observe(app.querySelector('.psn-sidebar'));app.addEventListener('pointerdown',focus,{capture:true});props.addEventListener('pointerdown',focus,{capture:true});const mo=new MutationObserver(()=>prepareToolCustomizers());const adminWin=document.querySelector('.window');if(adminWin)mo.observe(adminWin,{attributes:true,attributeFilter:['class']});window.addEventListener('tahoe-state-saved',()=>{renderTools();prepareToolCustomizers()})}

